Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'LANESTITEMLOCDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &lanestItemLocDescricao1.FromString(&GridStateDynamicFilter.Value) If not &lanestItemLocDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterlanestItemLocDescricaoDescription = format('%1 (%2)', "Unidade", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterlanestItemLocDescricaoDescription = format('%1 (%2)', "Unidade", "WWP_FilterContains") EndCase &lanestItemLocDescricao = &lanestItemLocDescricao1 print printBlockFilterlanestItemLocDescricao EndIf Case &DynamicFiltersSelector1 = !'LANESTITEMPRODDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &lanestItemProdDescricao1.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterlanestItemProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterlanestItemProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &lanestItemProdDescricao = &lanestItemProdDescricao1 print printBlockFilterlanestItemProdDescricao EndIf Case &DynamicFiltersSelector1 = !'LANESTITEMPRODCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &lanestItemProdCodigo1.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdCodigo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterlanestItemProdCodigoDescription = format('%1 (%2)', "Codigo", "=") EndCase &lanestItemProdCodigo = &lanestItemProdCodigo1 print printBlockFilterlanestItemProdCodigo EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'LANESTITEMLOCDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &lanestItemLocDescricao2.FromString(&GridStateDynamicFilter.Value) If not &lanestItemLocDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterlanestItemLocDescricaoDescription = format('%1 (%2)', "Unidade", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterlanestItemLocDescricaoDescription = format('%1 (%2)', "Unidade", "WWP_FilterContains") EndCase &lanestItemLocDescricao = &lanestItemLocDescricao2 print printBlockFilterlanestItemLocDescricao EndIf Case &DynamicFiltersSelector2 = !'LANESTITEMPRODDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &lanestItemProdDescricao2.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterlanestItemProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterlanestItemProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &lanestItemProdDescricao = &lanestItemProdDescricao2 print printBlockFilterlanestItemProdDescricao EndIf Case &DynamicFiltersSelector2 = !'LANESTITEMPRODCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &lanestItemProdCodigo2.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdCodigo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterlanestItemProdCodigoDescription = format('%1 (%2)', "Codigo", "=") EndCase &lanestItemProdCodigo = &lanestItemProdCodigo2 print printBlockFilterlanestItemProdCodigo EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'LANESTITEMLOCDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &lanestItemLocDescricao3.FromString(&GridStateDynamicFilter.Value) If not &lanestItemLocDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterlanestItemLocDescricaoDescription = format('%1 (%2)', "Unidade", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterlanestItemLocDescricaoDescription = format('%1 (%2)', "Unidade", "WWP_FilterContains") EndCase &lanestItemLocDescricao = &lanestItemLocDescricao3 print printBlockFilterlanestItemLocDescricao EndIf Case &DynamicFiltersSelector3 = !'LANESTITEMPRODDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &lanestItemProdDescricao3.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterlanestItemProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterlanestItemProdDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &lanestItemProdDescricao = &lanestItemProdDescricao3 print printBlockFilterlanestItemProdDescricao EndIf Case &DynamicFiltersSelector3 = !'LANESTITEMPRODCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &lanestItemProdCodigo3.FromString(&GridStateDynamicFilter.Value) If not &lanestItemProdCodigo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterlanestItemProdCodigoDescription = format('%1 (%2)', "Codigo", "=") EndCase &lanestItemProdCodigo = &lanestItemProdCodigo3 print printBlockFilterlanestItemProdCodigo EndIf EndCase EndIf EndIf EndIf If not (&TFlanestItemProdCodigo.IsEmpty() AND &TFlanestItemProdCodigo_To.IsEmpty()) print printBlockTFlanestItemProdCodigo &TFlanestItemProdCodigo_To_Description = format('%1 (%2)', "Codigo", "WWP_TSTo") print printBlockTFlanestItemProdCodigo_To EndIf If not &TFlanestItemProdDescricao_Sel.IsEmpty() print printBlockTFlanestItemProdDescricao_Sel Else If not &TFlanestItemProdDescricao.IsEmpty() print printBlockTFlanestItemProdDescricao EndIf EndIf If not (&TFlanestItemProdUni.IsEmpty() AND &TFlanestItemProdUni_To.IsEmpty()) print printBlockTFlanestItemProdUni &TFlanestItemProdUni_To_Description = format('%1 (%2)', "Unidade", "WWP_TSTo") print printBlockTFlanestItemProdUni_To EndIf If not (&TFlanestItemQuantidade.IsEmpty() AND &TFlanestItemQuantidade_To.IsEmpty()) print printBlockTFlanestItemQuantidade &TFlanestItemQuantidade_To_Description = format('%1 (%2)', "Quantidade", "WWP_TSTo") print printBlockTFlanestItemQuantidade_To EndIf If not (&TFlanestItemValidade.IsEmpty() AND &TFlanestItemValidade_To.IsEmpty()) print printBlockTFlanestItemValidade &TFlanestItemValidade_To_Description = format('%1 (%2)', "Validade", "WWP_TSTo") print printBlockTFlanestItemValidade_To EndIf If not &TFlanestItemObservacao_Sel.IsEmpty() print printBlockTFlanestItemObservacao_Sel Else If not &TFlanestItemObservacao.IsEmpty() print printBlockTFlanestItemObservacao EndIf EndIf If not &TFlanestItemLocDescricao_Sel.IsEmpty() print printBlockTFlanestItemLocDescricao_Sel Else If not &TFlanestItemLocDescricao.IsEmpty() print printBlockTFlanestItemLocDescricao EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
